mapper.select:
SELECT COALESCE(SUM(CASE WHEN co.state = 1 THEN co.amount ELSE 0 END), 0) as amount, COALESCE(SUM(CASE WHEN co.state = 1 THEN co.real_amount ELSE 0 END), 0) as realAmount, COUNT(*) as totalCount, COUNT(CASE WHEN co.state = 1 THEN 1 END) as successCount FROM tb_charge_order co LEFT JOIN tb_user u ON co.user_id = u.id LEFT JOIN sys_user agent_user ON u.agent = agent_user.id LEFT JOIN sys_user salesman_user ON u.salesmanid = salesman_user.id
AND u.agent = #{params.currentUserId}
AND u.salesmanid = #{params.currentUserId}
AND u.biaoqian = #{params.biaoqian}
AND u.biaoqian IS NOT NULL
AND u.biaoqian IS NULL
AND co.create_time >= FROM_UNIXTIME(#{params.createstarttime}/1000)
AND co.create_time <= FROM_UNIXTIME(#{params.createendtime}/1000)
AND co.create_time >= FROM_UNIXTIME(#{params.startTime}/1000)
AND co.create_time <= FROM_UNIXTIME(#{params.endTime}/1000)
AND co.orderno = #{params.orderno}
AND co.mobile LIKE CONCAT('%', #{params.mobile}, '%')
AND co.state = #{params.state}
AND co.threeorder_no LIKE CONCAT('%', #{params.threeorder_no}, '%')
